    size_t total = 1;
    for (int i = 0; i < count; i++) total += strlen(input[i]) + dlen;
    char *sb = malloc(total);
    sb[0] = '\0';
    for (int i = 0; i < count; i++) {
        strcat(sb, input[i]);
